// Proactive English B1 · Syria Edition · Book 1 · Unit 1 — Answer Key
const L = require('./lib');
const { p, h1, h2, pb, sp, box, table, C } = L;
const out = [];
const S = (t) => p(t, { bold: true, color: C.teal, before: 160, after: 60 });
const A = (t) => p(t, { indent: 200, after: 50 });
const SAMPLE = (paras) => box('Sample answer', paras, 'FFFFFF', C.navy);
const NOTE = (t) => box('Note', [t], C.lyellow, C.orange);

out.push(h1('Unit 1  First Impressions — Answer Key'));
out.push(p('_Proactive English · B1 · Book 1 · Syria Edition · Answer Key_', { color: '7F7F7F' }));
out.push(box('How to use this key', [
  'Every task has an answer or a **full sample**, including brainstorms, free speaking, reports, peer-review slips and homework.',
  '**This is the first unit of B1 and the first unit after two years of A2.** Four of the class have been together for twenty-four units and eight have never met them, and the unit is built on that: it is about first impressions because the room is full of them. Do not smooth it over by mixing the groups from the first minute — 1.1 to 1.3 work better if the four sit together once and the class notices.',
  '**One grammar point carries the unit** and it is not a new one: the present simple against the present continuous. What is new at B1 is the **test**. It is not "is it happening now" — it is whether the thing is the **arrangement** or a **departure** from it, and whether the sentence says for how long. _I work nights · this month I am working days, until the eighth of October._',
  '**State verbs are where the marks are.** _I don\'t understand_, never ~~I\'m not understanding~~. Students hear the wrong form on signs and in films all year, so correct it every time from the first lesson and do not explain it twice.',
  '**The past perfect is not taught yet.** It belongs to Unit 3 and this unit is written without a single one, on purpose, so that Unit 3 can own it. If a student produces one correctly, accept it, say it is Unit 3, and move on.',
], C.lblue, C.navy));

// ===================== 1.1 =====================
out.push(pb());
out.push(h2('1.1  Ninety seconds'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. The question at the end is the one that matters: the sentence people remember is almost always the fourth kind — the true thing nobody asked for. Collect three and write them up; they are the model for the whole cycle.'));
out.push(A('**b** **2** and **4** tell you something. **1** and **3** are labels: they are true, they are correct English, and they would fit two hundred people in this city. The point is not that 1 and 3 are wrong but that at B1 they are the **first four words**, not the answer.'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **B** – ninety seconds each, and she says she will time it.'));
out.push(A('**b** **1** Nothing — "a name on its own is worth nothing"; you have to say one thing that is true all the time and one that is true this month.   **2** That there is more, and that she will say it next week. Ms Huda accepts it and says she will hold her to it.'));
out.push(S('Language box · Practise'));
out.push(SAMPLE([
  '**1** I am a teacher. → _I teach mathematics at a secondary school in Rukn al-Din and I have taught it for twenty-four years._',
  '**2** I am from Aleppo. → _I am from Aleppo and I have lived in Damascus since 2014, which is longer than I lived there._',
  '**3** I use English at work. → _I use English about twice a week, always in writing, always to people I have never met._',
  '**4** I am a student. → _I am in the first year of computer engineering, and everything on the course is in English except the people._',
  '**5** I have a shop. → _I have a printing works in Qassaa — fourteen people, two machines, and the older machine is German and older than me._',
]));
out.push(S('Stage 3 · Practise (sample – Card A)'));
out.push(SAMPLE([
  '**A:** I\'m a nurse and I\'m from Deir ez-Zor.',
  '**B:** Is that all?',
  '**A:** I\'ve been a nurse for nine years. I use English for the families who come to us from outside Syria.',
  '**B:** And the thing nobody asks about?',
  '**A:** I work eleven nights a month, which means I will sometimes be in this room having been awake since the previous afternoon.',
  '**B:** That is the part I will remember.',
]));
out.push(S('Stage 3R · Perform – listener task (sample)'));
out.push(A('The fourth parts: _eleven nights a month_ · _everything on the course is in English except the people_ · _the older machine is German and older than me_. Ask which one the class will remember on Thursday and then actually ask again on Thursday; the prediction is nearly always right and the demonstration is worth more than the rule.'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '_Fares Kayyali. I represent a pharmaceutical company and I have done for six years. I am on the road three days a week — Homs on Mondays, Hama on Tuesdays, and back here on Wednesday night. I use English to read what the manufacturers send us, which arrives in English and is explained to the doctors by me, in Arabic, with me hoping I have understood it. That is the part nobody asks about: I am the last person in the chain who could notice a mistake, and I am the one who is least sure he would._',
  '**b** _Strongest: the last sentence. Missing: how long — he said "six years" and then never used a date again, so the ninety seconds had one number in it._',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Ms Huda gave everybody ninety seconds and said she would time it, because at A2 people said their name and their job and sat down, and by the second week nobody remembered anybody. She says a name on its own is worth nothing: you have to say one thing that is true all the time and one thing that is true this month. Lina has worked in accounts for four years and has been doing somebody else\'s job since June, which she is still not used to. Bassel has a printing works in Qassaa with fourteen people and two machines, and he buys from Türkiye and China through other people, which costs him money every month — that is why he is here. Yara has studied English since she was eleven and has never spoken it to a stranger, and when Ms Huda asked whether there was more she said there was and that she would say it next week.']));
out.push(S('Board clinic – typical mistakes'));
out.push(A('✗ I am working here since four years. → ✓ I **have worked** here **for** four years.   ✗ I am forty-one years. → ✓ I **am** forty-one.   ✗ I have fourteen persons. → ✓ fourteen **people**.   ✗ I am living in Damascus since 2014. → ✓ I **have lived** in Damascus since 2014.'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** For the families who come to them from outside Syria and do not speak Arabic — and she says it is **not** for promotion. Twice this year she has stood in front of a mother and been unable to tell her that her child was going to be all right.'));
out.push(A('**2** Between being good at English and being good at **understanding** English. He wants to say it in week one rather than be found out in week nine.'));
out.push(A('**3** Umm Kinan sees her son\'s daughters in Germany on a screen for twenty minutes, and says the same six sentences to them every week.'));
out.push(NOTE('Question 1 is the one to spend time on, because it is the model for every Stage 7 in the unit. Rasha does not give a reason, she gives a **scene**: a mother, four words, twice this year. Ask the class to find the reason-version of her paragraph — "I need medical English" — and then ask which one they would remember.'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**Tareq Ayoub.** I drive the Mezzeh minibus line and I have driven it for eleven years. I do the early shift, which starts at twenty past five, which is why I may be the one who falls asleep in this room and not Rasha. I need English for one reason and it is not the job: my brother\'s children are in Sweden and they come for one month every summer, and last August the older one stopped speaking Arabic to me halfway through a sentence and finished it in English, and I nodded. I would rather say now than in week nine that I nodded.',
]));
out.push(S('Stage 7 · Write freely (sample, 138 words)'));
out.push(SAMPLE([
  '**Lubna Sweidan.** I am in the final year of architecture at Damascus University and I have been a student for five years, which is one year longer than it says on the certificate I will get.',
  'I draw while people talk. It is not rudeness and it is not boredom: I hear better with a pencil moving, and I have been told off for it by four teachers and one aunt.',
  'I need English for the year after this one. Everything I want to read about my own subject was written in it, and the two books I have wanted most since 2022 do not exist in Arabic and are not going to.',
  'The thing I would rather say now than be found out for in week nine: I hear everything in this room and I say about a tenth of it. People are kind about that and call it listening. It is not listening, it is deciding not to risk anything, and I am twenty-three and I would like to stop.',
]));
out.push(S('Stage 7P · Respond (sample slip)'));
out.push(A('★ _"People are kind about that and call it listening." I want to ask you about that in June._   ✓ _"I need English for the year after this one" — true of eleven of us; the two books are yours._   ? _What is the thing you have not put in?_'));
out.push(S('Stage 7R · Share'));
out.push(A('Pin them up and do the name-matching before anybody has read them properly; expect three or four out of twelve. The exercise is repeated in Unit 12 with the same pages, and the number is usually ten or eleven — which is a better argument for writing specifically than anything you can say.'));
out.push(S('Homework (sample)'));
out.push(SAMPLE(['**What I would have said two years ago:** "My name is Tareq. I am a driver. I am from Damascus. I am married and I have two children." **What is in the new one that is not in that:** the eleven years, the time the shift starts, and my brother\'s children in Sweden. The old one has four facts and no reason in it. The part that surprises me is that two years ago I would have thought the old one was more polite, because it does not ask anybody to be interested.']));

// ===================== 1.2 =====================
out.push(pb());
out.push(h2('1.2  What I do and what I\'m doing'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open, and fast. Keep the two columns on the board for the whole lesson; everything in the cycle is read against them.'));
out.push(A('**b** **1** I **work** at the children\'s hospital _(permanent, nine years)_   **2** This month I **am working** on days   **3** I **understand** what you mean _(state verb)_   **4** I **am trying** to improve my writing _(at the moment)_'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **B** – the sister who does days is in Lebanon until the eighth of October.'));
out.push(A('**b** **1** Writing down every fault — the date, the model, what was wrong and what he did; four weeks so far.   **2** That it is a **state verb**: _I don\'t understand_, not ~~I\'m not understanding~~. She points out that Jad said it correctly without noticing.'));
out.push(S('Language box · Practise'));
out.push(A('**1** I **work** nights.   **2** This week I **am covering** for somebody.   **3** I **don\'t understand** the question.   **4** He **is thinking** about leaving.   **5** She **knows** the answer.   **6** They **are building** a new entrance this month.'));
out.push(NOTE('Items 4 and 5 are the pair that teaches the rule: _think_ takes the continuous when it is an **activity** (he is turning it over) and the simple when it is an **opinion**; _know_ never takes it at all. If a student can explain why 4 and 5 differ, they have the cycle.'));
out.push(S('Stage 3 · Practise (sample – Card A)'));
out.push(SAMPLE([
  '**A:** I work nights at the hospital.',
  '**B:** And at the moment?',
  '**A:** This month I\'m working days, because the day sister is in Lebanon.',
  '**B:** How long for?',
  '**A:** Until the eighth of October.',
  '**B:** And do you prefer it?',
  '**A:** No. I know that sounds strange and I don\'t think I can explain it in English yet.',
]));
out.push(S('Stage 3R · Perform – listener task (sample)'));
out.push(A('Permanent: _I work nights · I open the shop at eight · I teach mathematics._ Temporary: _this month I am working days · I am opening at seven until the road reopens · I am taking two classes while Samih is away._ The words that mark the difference are nearly always **this month**, **until** and **while**; get the class to underline those three rather than the verbs.'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '**a** _Permanent: I live with my parents · I work in a laboratory · I take the same bus every morning. Temporary: I am doing the evening shift this term, because the centre is only open late on the days I can come._',
  '**b** _The thing that has been temporary for more than a year: I have been "helping out" in my uncle\'s shop on Saturdays since 2023. We still both call it helping out. It is a job._',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Rasha works nights but this month she is working days, because the sister who does days is in Lebanon until the eighth of October. She prefers nights, which everybody tells her is strange: on nights there are four of them and nobody is watching and you do the job, and on days there are fourteen and half her hours go on explaining what she has just done to somebody who was not there. Mazen mends telephones, which does not change, but what he is doing this month is writing down every fault with the date, the model and what he did — four weeks so far — because a man asked him how many of a model come in with a fault, he said "a lot", the man said "how many", and he did not know. Jad said he did not understand why it mattered, and Ms Huda stopped him to point out that he said it correctly without noticing.']));
out.push(S('Board clinic – typical mistakes'));
out.push(A('✗ I am not understanding. → ✓ I **don\'t understand**.   ✗ I am knowing him for ten years. → ✓ I **have known** him for ten years.   ✗ This month I work days. → ✓ This month I **am working** days.   ✗ I am living here since 2014. → ✓ I **have lived** here since 2014.'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** Not the record itself — that he has stopped saying "a lot".'));
out.push(A('**2** "To be fifty and a beginner on a Monday and an expert on a Tuesday."'));
out.push(A('**3** Because she says it is the truest sentence on the page and somebody should say it — that she is doing nothing differently at all.'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**My father** drives, as he always has, and this autumn he is taking the Aleppo run once a week instead of twice. One month so far. He says he does not mind and the house says otherwise.',
  '**My sister** teaches and is covering another class until the new teacher arrives, which was supposed to be September.',
  '**My mother** runs the house, as she has for thirty years, and this year is learning to use the bank\'s application on her telephone, which my brother set up for her in April and which she has used nine times without once asking him anything.',
  '**I** am doing nothing differently at all, which is the truest line here and I am leaving it in.',
]));
out.push(S('Stage 7 · Write freely (sample, 127 words)'));
out.push(SAMPLE([
  '**WHAT WE ARE EACH DOING THIS TERM** · the third floor, building 14',
  '**Abu Samir** opens the door for everybody, as he has since before we came, and this autumn he is doing it with a stick. Six weeks. He says the stick is temporary and the doctor says it is not.',
  '**Umm Rami** cleans the stairs on Fridays and is cleaning them on Tuesdays as well, because the builders in flat 4 come on Mondays. She is not being paid more and she has not asked.',
  '**Flat 3** keep themselves to themselves, as they always have, and this month are leaving their door open in the afternoons, which nobody has mentioned to them and everybody has mentioned to each other.',
  '**My mother** is doing nothing differently at all. She says this is what a building is supposed to be like and that the rest of us are making a fuss about a stick and a door.',
]));
out.push(S('Stage 7P · Respond (sample slip)'));
out.push(A('★ _"which nobody has mentioned to them and everybody has mentioned to each other" — I know that building now._   ✓ _Abu Samir\'s entry: I cannot tell whether the stick is the usual thing or the new thing until the second sentence._   ? _Will the open door still be true at the end of the year?_'));
out.push(S('Stage 7R · Share'));
out.push(A('Take the vote, write it down, date it and keep it with the Unit 1 envelopes. It is opened in Unit 12 alongside the first-impressions notes, and the two together make the Unit 12 Review & Mediate cycle work.'));
out.push(S('Homework (sample)'));
out.push(SAMPLE(['I work in the laboratory from eight until four, six days, as I have for three years. What I am doing differently is coming here on Monday and Thursday evenings, which means I get home at eight and eat at half past — and my mother has moved dinner for the whole house by ninety minutes, without being asked and without mentioning it. I expect the difference to last until June. I do not expect the dinner time to go back.']));

// ===================== 1.3 =====================
out.push(pb());
out.push(h2('1.3  Four questions and a fifth'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. Ask the same four students the same bare question and let the class hear four short answers before anybody analyses anything. The silence after the fourth is the lesson.'));
out.push(A('**b** **2** and **4** get more than one word. **1** and **3** are doors, not conversations — and the point to make is that they are not **wrong**: a closed question is the right way to open, provided something follows it.'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **B** – he gets a much longer answer.'));
out.push(A('**b** **1** Three of the four can be answered with one word and the fourth with a number.   **2** _How did you end up with a printing works?_ — his father had it, he did not want it, he was going to be a pharmacist and failed the year twice, his father stopped speaking to him about it, then had a heart attack in 2006, somebody had to open the place on the Monday and it was him. He says the strange part is that he is good at it.'));
out.push(S('Language box · Practise'));
out.push(A('**1** _What is the best part of your job, and what is the worst?_   **2** _What would you change about your flat if you could?_   **3** _What do you remember about the first time you went?_   **4** _What made it difficult?_   **5** _What do you use English for that you did not expect to?_'));
out.push(S('Stage 3 · Practise (sample – Card A)'));
out.push(SAMPLE([
  '**A:** Do you like living in Damascus?',
  '**B:** Yes.',
  '**A:** How did you end up living here?',
  '**B:** I came for one year, in 2014, to finish a course. The course finished. I am still here. The strange part is that I now find Suwayda loud, which anybody from Suwayda would tell you is impossible.',
  '**A:** And what do people get wrong about it?',
  '**B:** That I chose it. Nobody chose anything in 2014 and I am tired of pretending I had a plan.',
]));
out.push(S('Stage 3R · Perform – listener task (sample)'));
out.push(A('The open question and the first sentence it produced. The longest answers come from _how did you end up…?_ — the only one of the four that asks for a **story** rather than an opinion, and the one almost nobody has ever been asked.'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '**a** _Three minutes, one closed question allowed. Keep the answers: 1.7 needs them._',
  '**b** _What surprised me about my own answer: I was asked what people get wrong about my work and I said "that it is boring", and then I heard myself say that I find it boring on about two days in five and that those are the days I do it best. I have never said that to anybody, including myself._',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Jad asked Bassel four questions and got four short answers: he has a printing works, yes he likes it, not very big, nineteen years. He said Bassel was not giving him anything, and Ms Huda said Bassel was giving him exactly what he asked for, because three of the four could be answered in one word and the fourth with a number. So Jad asked how he ended up with a printing works, and got ninety seconds: his father had it, he did not want it, he was going to be a pharmacist and failed the year twice, and in the second year his father stopped speaking to him about it, which Bassel says was worse than the shouting. Then his father had a heart attack in 2006, somebody had to open the place on the Monday, it was him, and he has opened it every Monday since. He says the strange part is that he is good at it.']));
out.push(S('Board clinic – typical mistakes'));
out.push(A('✗ How you end up there? → ✓ How **did** you end up there?   ✗ What means "despatch"? → ✓ What **does** "despatch" **mean**?   ✗ You are from where? → ✓ **Where are** you from?   ✗ Why you came here? → ✓ Why **did** you come here?'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** Eleven words.'));
out.push(A('**2** Not being rude — being **accurate**. They are answering exactly what was asked.'));
out.push(A('**3** His uncle, whom he has also known for nineteen years, told him something he did not know about his first job.'));
out.push(NOTE('The second use is the part of the page that makes it a method rather than an anecdote, and it is the part students leave out of their own Stage 7. Say so before they write, not after: the page has to end with the technique working on somebody else.'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**THE QUESTION I DID NOT ASK** · Rasha Barakat',
  'I asked a mother four questions on Tuesday and got four nods, and I asked a fifth and found out that she last ate the day before.',
  '**What I asked, and what I got.** _Is he comfortable?_ — a nod. _Is the room warm enough?_ — a nod. _Do you need anything?_ — "No, thank you." _Have you been here all night?_ — a nod.',
  '**What somebody pointed out.** The sister on nights said I ask questions that let people say no, and that a woman who has not eaten will say no to "do you need anything" every time.',
  '**The thing that worked.** _When did you last eat something?_ Four seconds. The answer was "yesterday, before we came in."',
  '**What I am taking from it.** I have stopped asking "do you need anything". I used the new question on a father on Friday and he said "I don\'t know", which took me two more questions, and he was in the same state.',
]));
out.push(S('Stage 7 · Write freely (sample, 131 words)'));
out.push(SAMPLE([
  '**ELEVEN YEARS AND ONE QUESTION** · Tareq Ayoub',
  'I have driven the same line for eleven years and I asked a passenger a real question for the first time in September, by accident.',
  '**What I usually say.** "Where to?" — a place. "Have you got change?" — yes or no. Eleven years, two questions, forty passengers a day. Somebody worked out once that I have said "where to" about a hundred thousand times.',
  '**What happened.** An old man got on at the same stop he gets on at every Tuesday and I said, without planning it, "what is in Mezzeh on a Tuesday?" He said: his wife is in the hospital there and has been since March, and Tuesday is the day they let him stay in the afternoon.',
  '**What I am taking from it.** I have known that man by sight for two years. I knew where he got on and where he got off and nothing else, and I would have said I knew him.',
  '**The second time.** I asked the woman with the two bags the same kind of question on Thursday. She sells bread in Sahnaya and starts at four in the morning. Two years of "where to".',
]));
out.push(S('Stage 7P · Respond (sample slip)'));
out.push(A('★ _"Eleven years, two questions, forty passengers a day." The arithmetic is the whole page._   ✓ _"I would have said I knew him" — you tell me it is sad; let me find that._   ? _Did the second one work, or are you being kind to yourself?_'));
out.push(S('Stage 7R · Share'));
out.push(A('Make everybody write the four questions inside the cover of the notebook **in the lesson**, and make them say out loud who they will use one on before Thursday. In a class of twelve about eight then do it; where it is left as a suggestion, about two.'));
out.push(S('Homework (sample)'));
out.push(SAMPLE(['I asked my mother what the hardest part of her job was. She worked in a pharmacy from 1989 to 2004 and I have never asked her one question about it. She said the hardest part was that people told her things they did not tell their own families, because a pharmacy is not a doctor and there is no appointment, and that she carried other people\'s news around for fifteen years and never once said any of it at home. I did not know she minded. I did not know she remembered. She then asked me why I was asking, and I said it was homework, and she laughed and said that was the most honest answer I have given her this year.']));

// ===================== 1.4 =====================
out.push(pb());
out.push(h2('1.4  What she\'s like'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Give behaviour, never character: _she arrived first and sat at the back_. The class will produce a character word immediately — that is the instinct the cycle is working on — and the second question, what else it could mean, is where the learning is.'));
out.push(A('**b** **1** What is she **like**?   **2** She seems nice _(nothing)_   **3** He comes across **as** confident.   **4** She strikes me **as** somebody who has done this before.'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **B** – Yara.'));
out.push(A('**b** **1** That saying four sentences and then saying there is more is not shyness — it is somebody **deciding**; and that whether she is quiet is a different question from how she comes across, after two hours.   **2** Lina. For about three months he thought she was cold; she is not cold, she is careful, and he says those look identical from the outside until the day you need something.'));
out.push(S('Language box · Practise'));
out.push(SAMPLE([
  '**1 confident** — _He is confident._ · _He seems confident._ · _He strikes me as somebody who has done this in front of people before._',
  '**2 reserved** — _She is reserved._ · _She comes across as reserved._ · _I\'d say she is reserved with the eight of us and not with the four she knows._',
  '**3 reliable** — _He is reliable._ · _He seems reliable._ · _He strikes me as somebody who would tell you if he could not do it._',
  '**4 impatient** — _She is impatient._ · _She can come across as impatient._ · _I\'d say she is quick rather than impatient, which is not the same thing._',
  '**5** — _She strikes me as somebody who has done this before, because she asked what the assessment was in the first ten minutes._',
]));
out.push(S('Stage 3 · Practise (sample – Card A)'));
out.push(SAMPLE([
  '**A:** She arrived first and sat at the back.',
  '**B:** She comes across as somebody who wants to watch before she joins in.',
  '**A:** Or?',
  '**B:** Or the back row is the only one she can hear from, which looks the same from the front.',
  '**A:** How long have we known her?',
  '**B:** Two hours. So what I can say is how she comes across, not what she is like.',
]));
out.push(S('Stage 3R · Perform – listener task (sample)'));
out.push(A('The two readings of each behaviour. The second reading is nearly always both kinder **and** more likely, and it is worth saying so out loud — the generous reading is not a politeness exercise, it is usually the better bet. _He answered before the question was finished_: eager, or he has been told all his life that he is slow and is proving otherwise.'));
out.push(S('Stage 4 · Your turn (sample)'));
out.push(SAMPLE([
  '**a** _She has not spoken for two weeks, she writes everything down, and she came to ask me a question in the break rather than in the room. She comes across as reserved. I have known her two weeks._ — **Yara.**',
  '**b** _The person I got completely wrong: my supervisor in my first job. I thought he did not like me for a year. He was deaf in one ear and I always sat on that side, and nobody told me, including him._',
]));
out.push(S('Stage 4R · Report (sample)'));
out.push(SAMPLE(['Samira said Bassel talks and Jad talks faster, and that the one she noticed is Yara — because Yara said four sentences and then said there was more and that she would say it next week, which Samira says is not shyness, it is somebody deciding. Tareq said she comes across as quiet and Samira agreed, but said that whether she is quiet is a different question and they have known her for two hours. Omar said he got somebody completely wrong at A2: for three months he thought Lina was cold, and she is not cold, she is careful, and those look identical from the outside until the day you need something. What changed it was the printing business in the spring, when everybody was angry and useless and Lina sat down and wrote the letter that got the money back at ten o\'clock at night, for somebody else\'s problem. His rule now is to say how somebody comes across and to say that it is after two hours, because those are two sentences and the second one is the honest half.']));
out.push(S('Board clinic – typical mistakes'));
out.push(A('✗ She seems like quiet. → ✓ She **seems** quiet. / She seems **like a quiet person**.   ✗ He comes across confident. → ✓ comes across **as** confident.   ✗ What is she like? — She likes swimming. → ✓ two different questions.   ✗ He strikes me like somebody who… → ✓ strikes me **as**.'));
out.push(S('Stage 5 · Read'));
out.push(A('**1** She is wrong about a third of it every year, and that is the reason she keeps writing it down — she seals it in week one and reads it in June.'));
out.push(A('**2** That every year there is one person who is not shy but deciding, and that those are the ones who are still there in June.'));
out.push(A('**3** Not that Lina could not be made to speak, but **by whom, in front of how many people, and when**: by her, in front of eleven people, in week three. In May Lina argued with her about a tense, in English, and was right.'));
out.push(NOTE('Answer 3 is the writing lesson of the cycle. "I was wrong about her" teaches nobody anything; naming the **mechanism** of the error is what makes a first-impressions note worth keeping. Students who get this write a different Stage 7 — and it is the same move as the "half of it is mine" line in 1.5.'));
out.push(S('Stage 6 · Write with help (sample)'));
out.push(SAMPLE([
  '**WHAT I THINK AFTER THREE SHIFTS** · the new ward · _not shown to anybody_',
  'I write this after three shifts and I read it again at the end of the winter.',
  '**The sister in charge** comes across as strict. She may be; she may also be the only person on the ward who writes everything down, which looks like strictness from underneath. I will know by December.',
  '**The young one from Hama** strikes me as the best nurse here and the one who will be gone by spring, because she is the only one who is still angry about things, and people who are still angry either change the place or leave it.',
  '**And what I got wrong last time:** "The porters do not listen." I was wrong, and the way I was wrong matters — they do not listen to people who talk to them from behind a desk, which for two years was me.',
]));
out.push(S('Stage 7 · Write freely (sample, 144 words)'));
out.push(SAMPLE([
  '**WHAT I THINK AFTER TWO WEEKS** · Class 5A · Bassel Tahhan · _not shown to anybody_',
  'I am forty-one and I am writing a page about people I have met twice, which at twenty-five I would have thought was a waste of an evening.',
  '**Jad** comes across as somebody who knows everything. He may be; he may also be nineteen in a room where everybody else has a job, and doing the only thing that works at nineteen in that room. I will know when he is wrong about something in front of us.',
  '**Yara** said four sentences and stopped. I thought: shy. Samira said: deciding. Samira has been in a class with eleven strangers more recently than I have, and I am writing her reading down and not mine.',
  '**Lina** needs four seconds before she speaks and I do not leave four seconds. That is the only line on this page that is about me and it is the only one I can do anything about.',
  '**And what I got wrong last time:** "The new man at the works will not last." He has been with me six years. The way I was wrong matters — I decided it in his first fortnight, and then spent two months finding evidence for it.',
]));
out.push(S('Stage 7P · Respond (sample slip)'));
out.push(A('★ _"then spent two months finding evidence for it." That is the most honest sentence anybody has written in this class._   ✓ _The Jad entry is an impression; the Yara entry is a verdict with somebody else\'s name on it._   ? _What would make you change your mind about Jad?_'));
out.push(S('Stage 7R · Share'));
out.push(A('Seal them, name on the front, and keep them with the Unit 1 pages and the Unit 1.2 vote. All three come back in Unit 12. The question in Unit 12 is deliberately not "were you right" — it is **which kind of thing were you wrong about**, and the answer is nearly always the same kind for the same student, which is the only genuinely useful thing a first-impressions note can tell anybody.'));
out.push(S('Homework (sample)'));
out.push(SAMPLE(['**What somebody wrote about me in their first week, probably.** "Bassel talks." The alternative reading, if they were being fair: he has run a place with fourteen people in it for nineteen years and has had nobody to talk to about it in all that time, because you cannot talk to the fourteen about the fourteen. The date by which they will know: the first week I am quiet, which will be the week I have understood that the room will keep going without me filling it.']));

// ===================== 1.5 =====================
out.push(pb());
out.push(h2('1.5  Without saying anything unkind'));
out.push(S('Stage 1 · Get ready'));
out.push(A('**a** Open. The second question — which of the six would you say **to him** — is the one that separates hedging from avoiding, and it is worth the whole six minutes.'));
out.push(A('**b** Samples: **1** _She can be a bit reserved at first._   **2** _He tends to pick his moments._   **3** _She can be quick to come in._   **4** _I\'d say email is not the best way to reach him._'));
out.push(NOTE('**2** is the trap and it is worth doing on the board. ~~He is a bit lazy~~ is not softer than _he is lazy_ — the hard word is still in the sentence and now you have been mealy about it as well. The rule: change the **word**, not the volume.'));
out.push(S('Stage 2 · Listen and read'));
out.push(A('**a** **C** – that Bassel is doing something she recognises; she was like him in her own first year.'));
out.push(A('**b** **1** Certain about everything, for about eight months.   **2** It is **not** politeness and it is **not** weakness — it is a form you can be wrong in without having insulted anybody.'));
out.push(S('Language box · Practise'));
out.push(A('**1** _She can be a bit reserved at first._   **2** _I\'d say email is not the best way to reach him._   **3** _She tends to come in before people have finished._   **4** _He can be hard to get hold of in the mornings._   **5** _I\'d say her writing goes faster than her checking._'));
out.push(S('Stage 3 · Practise (sample – Card A)'));
